// Servidor do Maxx: entrega o app (pasta public) e a API (/api/...).
import express from 'express';
import path from 'node:path';
import { fileURLToPath } from 'node:url';
import { initDb, q, one, dbKind } from './db.js';
import { config } from './config.js';
import { MEDAL_TYPES, MEDAL_BY_CODE, TROPHIES, TROPHY_BY_CODE, POINT_RULES, POINTS } from './rules.js';
import {
  HttpError, createPost, deletePost, toggleLike, addComment, deleteComment, giveMedal, revokeMedal,
  ranking, positions, totalPoints, getStats, checkTrophies, saveImageFromDataUrl,
} from './services.js';
import {
  hashPassword, checkPassword, createSession, destroySession, loadUser, requireUser, rateLimit, PUBLIC_USER_FIELDS,
} from './auth.js';
import { seedIfEmpty } from './seed.js';

const here = path.dirname(fileURLToPath(import.meta.url));
const publicDir = path.join(here, '..', 'public');

const int = (v) => {
  const n = Number.parseInt(v, 10);
  return Number.isFinite(n) ? n : null;
};
const clean = (v, max) => String(v ?? '').trim().slice(0, max);

function requireRole(...roles) {
  return (req, _res, next) => {
    if (!req.user) throw new HttpError(401, 'Faça login para continuar.');
    if (!roles.includes(req.user.role)) throw new HttpError(403, 'Você não tem permissão para isso.');
    next();
  };
}

function meJson(u) {
  return {
    id: u.id, name: u.name, role: u.role, email: u.email, course_id: u.course_id, course: u.course,
    course_name: u.course_name, semester: u.semester, bio: u.bio, avatar_id: u.avatar_id, is_guest: u.is_guest,
  };
}

// Consulta base do feed: publicação + autor + contadores + detalhes de medalha.
const FEED_SELECT = `
  SELECT p.id, p.kind, p.image_id, p.caption, p.ref_code, p.created_at,
         u.id AS user_id, u.name AS user_name, u.avatar_id AS user_avatar, u.role AS user_role, u.is_guest AS user_guest,
         c.short AS user_course,
         (SELECT count(*) FROM likes l WHERE l.post_id = p.id)::int AS likes,
         (SELECT count(*) FROM comments cm WHERE cm.post_id = p.id)::int AS comments,
         EXISTS (SELECT 1 FROM likes l WHERE l.post_id = p.id AND l.user_id = $1) AS liked,
         m.id AS medal_id, m.type AS medal_type, m.reason AS medal_reason,
         pr.id AS prof_id, pr.name AS prof_name
    FROM posts p
    JOIN users u ON u.id = p.user_id
    LEFT JOIN courses c ON c.id = u.course_id
    LEFT JOIN medals m ON p.kind = 'medalha' AND m.id = p.ref_id
    LEFT JOIN users pr ON pr.id = m.professor_id`;

function decoratePost(p) {
  if (p.kind === 'medalha') p.medal = MEDAL_BY_CODE[p.medal_type] || null;
  if (p.kind === 'trofeu') p.trophy = TROPHY_BY_CODE[p.ref_code] || null;
  return p;
}

export async function createApp({ dataDir } = {}) {
  await initDb({ dataDir });
  if (config.seedDemo) await seedIfEmpty();

  const app = express();
  app.set('trust proxy', 1); // Render/Cloudflare ficam na frente: confia no HTTPS deles
  app.disable('x-powered-by');
  app.use(express.json({ limit: '8mb' }));
  app.use((_req, res, next) => {
    res.set('X-Content-Type-Options', 'nosniff');
    res.set('Referrer-Policy', 'same-origin');
    next();
  });
  app.use('/api', loadUser);

  // ---------- Público ----------
  app.get('/api/health', (_req, res) => res.json({ ok: true, db: dbKind() }));

  app.get('/api/config', async (_req, res) => {
    const courses = await q('SELECT id, name, short FROM courses ORDER BY name');
    res.json({
      emailDomains: config.emailDomains,
      bancaEnabled: config.bancaEnabled,
      bancaNeedsCode: Boolean(config.bancaCode),
      courses,
      medalTypes: MEDAL_TYPES,
      pointRules: POINT_RULES,
      postPoints: POINTS.post,
    });
  });

  app.get('/api/img/:id', async (req, res) => {
    const img = await one('SELECT mime, data FROM images WHERE id = $1', [int(req.params.id)]);
    if (!img) throw new HttpError(404, 'Imagem não encontrada.');
    res.set('Content-Type', img.mime);
    res.set('Cache-Control', 'public, max-age=31536000, immutable');
    if (img.mime === 'image/svg+xml') res.set('Content-Security-Policy', "default-src 'none'; style-src 'unsafe-inline'");
    res.send(Buffer.from(img.data));
  });

  // ---------- Conta ----------
  app.post('/api/auth/register', rateLimit(20), async (req, res) => {
    const name = clean(req.body.name, 80);
    const email = clean(req.body.email, 120).toLowerCase();
    const password = String(req.body.password || '');
    const role = req.body.role === 'professor' ? 'professor' : 'aluno';
    if (name.length < 3) throw new HttpError(400, 'Digite seu nome completo.');
    if (!/^[^@\s]+@[^@\s]+$/.test(email)) throw new HttpError(400, 'E-mail inválido.');
    const domain = email.split('@')[1];
    if (!config.emailDomains.includes(domain)) {
      throw new HttpError(400, `Use seu e-mail institucional (${config.emailDomains.map((d) => '@' + d).join(' ou ')}).`);
    }
    if (password.length < 6) throw new HttpError(400, 'A senha precisa ter pelo menos 6 caracteres.');
    let courseId = null;
    let semester = null;
    if (role === 'professor') {
      if (clean(req.body.professorCode, 60).toUpperCase() !== config.professorCode.toUpperCase()) {
        throw new HttpError(400, 'Código de professor incorreto. Peça para a coordenação.');
      }
    } else {
      courseId = int(req.body.course_id);
      if (!courseId || !(await one('SELECT id FROM courses WHERE id = $1', [courseId]))) throw new HttpError(400, 'Escolha seu curso.');
      semester = Math.min(Math.max(int(req.body.semester) || 1, 1), 12);
    }
    if (await one('SELECT id FROM users WHERE email = $1', [email])) throw new HttpError(409, 'Já existe uma conta com esse e-mail.');
    const u = await one(
      `INSERT INTO users (email, password_hash, name, role, course_id, semester)
       VALUES ($1, $2, $3, $4, $5, $6) RETURNING id`,
      [email, hashPassword(password), name, role, courseId, semester],
    );
    await createSession(res, req, u.id);
    res.json({ ok: true });
  });

  app.post('/api/auth/login', rateLimit(30), async (req, res) => {
    const email = clean(req.body.email, 120).toLowerCase();
    const u = await one('SELECT id, password_hash FROM users WHERE email = $1', [email]);
    if (!u || !checkPassword(req.body.password || '', u.password_hash)) throw new HttpError(401, 'E-mail ou senha incorretos.');
    await createSession(res, req, u.id);
    res.json({ ok: true });
  });

  // Acesso rápido da banca: cria uma conta de visitante (sem e-mail e sem senha).
  app.post('/api/auth/banca', rateLimit(30), async (req, res) => {
    if (!config.bancaEnabled) throw new HttpError(403, 'O acesso da banca está desligado.');
    if (config.bancaCode && clean(req.body.code, 60).toLowerCase() !== config.bancaCode.toLowerCase()) {
      throw new HttpError(400, 'Código da banca incorreto.');
    }
    const name = clean(req.body.name, 60);
    if (name.length < 2) throw new HttpError(400, 'Digite seu nome.');
    const role = req.body.role === 'professor' ? 'professor' : 'aluno';
    let courseId = null;
    if (role === 'aluno') {
      courseId = int(req.body.course_id);
      if (!courseId || !(await one('SELECT id FROM courses WHERE id = $1', [courseId]))) throw new HttpError(400, 'Escolha um curso.');
    }
    const u = await one(
      `INSERT INTO users (name, role, course_id, semester, is_guest, bio)
       VALUES ($1, $2, $3, $4, TRUE, $5) RETURNING id`,
      [name, role, courseId, role === 'aluno' ? 8 : null, 'Membro da banca avaliadora 🎓'],
    );
    await createSession(res, req, u.id, 7);
    res.json({ ok: true });
  });

  app.post('/api/auth/logout', async (req, res) => {
    await destroySession(req, res);
    res.json({ ok: true });
  });

  app.get('/api/me', (req, res) => {
    res.json({ user: req.user ? meJson(req.user) : null });
  });

  app.put('/api/me', requireUser, async (req, res) => {
    const u = req.user;
    const name = clean(req.body.name ?? u.name, 80);
    if (name.length < 2) throw new HttpError(400, 'Nome muito curto.');
    const bio = clean(req.body.bio ?? u.bio, 300);
    let courseId = u.course_id;
    let semester = u.semester;
    if (u.role === 'aluno') {
      const c = int(req.body.course_id);
      if (c && (await one('SELECT id FROM courses WHERE id = $1', [c]))) courseId = c;
      const s = int(req.body.semester);
      if (s) semester = Math.min(Math.max(s, 1), 12);
    }
    let avatarId = u.avatar_id;
    if (req.body.avatar) {
      avatarId = await saveImageFromDataUrl(req.body.avatar, u.id);
    }
    await q('UPDATE users SET name = $1, bio = $2, course_id = $3, semester = $4, avatar_id = $5 WHERE id = $6', [
      name, bio, courseId, semester, avatarId, u.id,
    ]);
    if (avatarId !== u.avatar_id && u.avatar_id) await q('DELETE FROM images WHERE id = $1', [u.avatar_id]);
    const trophies = await checkTrophies(u.id);
    res.json({ ok: true, trophies });
  });

  // ---------- Feed e publicações ----------
  app.get('/api/feed', requireUser, async (req, res) => {
    const before = int(req.query.before);
    const userId = int(req.query.user);
    const courseId = req.query.scope === 'course' ? req.user.course_id : null;
    const kind = req.query.kind === 'foto' ? 'foto' : null;
    const limit = Math.min(int(req.query.limit) || 12, 60);
    const rows = await q(
      `${FEED_SELECT}
       WHERE ($2::int IS NULL OR (p.created_at, p.id) < (SELECT created_at, id FROM posts WHERE id = $2))
         AND ($3::int IS NULL OR u.course_id = $3)
         AND ($4::int IS NULL OR p.user_id = $4)
         AND ($5::text IS NULL OR p.kind = $5)
       ORDER BY p.created_at DESC, p.id DESC LIMIT ${limit}`,
      [req.user.id, before, courseId, userId, kind],
    );
    res.json({ posts: rows.map(decoratePost), more: rows.length === limit });
  });

  app.post('/api/posts', requireUser, async (req, res) => {
    res.json(await createPost(req.user, req.body));
  });

  app.get('/api/posts/:id', requireUser, async (req, res) => {
    const post = await one(`${FEED_SELECT} WHERE p.id = $2`, [req.user.id, int(req.params.id)]);
    if (!post) throw new HttpError(404, 'Publicação não encontrada.');
    const comments = await q(
      `SELECT cm.id, cm.body, cm.created_at, u.id AS user_id, u.name AS user_name, u.avatar_id AS user_avatar,
              u.role AS user_role, u.is_guest AS user_guest
         FROM comments cm JOIN users u ON u.id = cm.user_id
        WHERE cm.post_id = $1 ORDER BY cm.id ASC`,
      [post.id],
    );
    res.json({ post: decoratePost(post), comments });
  });

  app.delete('/api/posts/:id', requireUser, async (req, res) => {
    await deletePost(req.user, int(req.params.id));
    res.json({ ok: true });
  });

  app.post('/api/posts/:id/like', requireUser, async (req, res) => {
    res.json(await toggleLike(req.user, int(req.params.id)));
  });

  app.post('/api/posts/:id/comments', requireUser, async (req, res) => {
    res.json(await addComment(req.user, int(req.params.id), req.body.body));
  });

  app.delete('/api/comments/:id', requireUser, async (req, res) => {
    await deleteComment(req.user, int(req.params.id));
    res.json({ ok: true });
  });

  // ---------- Pessoas ----------
  app.get('/api/users', requireUser, async (req, res) => {
    const term = clean(req.query.q, 60);
    const role = req.query.role === 'aluno' ? 'aluno' : null;
    const rows = await q(
      `SELECT u.id, u.name, u.role, u.avatar_id, u.is_guest, u.semester, c.short AS course
         FROM users u LEFT JOIN courses c ON c.id = u.course_id
        WHERE ($1::text = '' OR u.name ILIKE '%' || $1 || '%')
          AND ($2::text IS NULL OR u.role = $2)
        ORDER BY u.name LIMIT 30`,
      [term, role],
    );
    res.json({ users: rows });
  });

  app.get('/api/users/:id', requireUser, async (req, res) => {
    const u = await one(
      `SELECT ${PUBLIC_USER_FIELDS}, c.name AS course_name, c.short AS course
         FROM users u LEFT JOIN courses c ON c.id = u.course_id WHERE u.id = $1`,
      [int(req.params.id)],
    );
    if (!u) throw new HttpError(404, 'Pessoa não encontrada.');
    const out = { user: u };
    if (u.role === 'aluno') {
      out.points = await totalPoints(u.id);
      out.positions = await positions(u);
      out.stats = await getStats(u.id);
      out.trophies = (await q('SELECT code, unlocked_at FROM user_trophies WHERE user_id = $1 ORDER BY unlocked_at DESC', [u.id]))
        .map((t) => ({ ...TROPHY_BY_CODE[t.code], unlocked_at: t.unlocked_at }))
        .filter((t) => t.code);
      out.medals = (await q('SELECT type, count(*)::int AS n FROM medals WHERE student_id = $1 GROUP BY type', [u.id]))
        .map((m) => ({ ...MEDAL_BY_CODE[m.type], count: m.n }))
        .filter((m) => m.code);
    } else {
      const given = await one('SELECT count(*)::int AS n FROM medals WHERE professor_id = $1', [u.id]);
      const notices = await one('SELECT count(*)::int AS n FROM notices WHERE author_id = $1', [u.id]);
      out.medalsGiven = given.n;
      out.noticesCount = notices.n;
    }
    res.json(out);
  });

  // ---------- Conquistas ----------
  app.get('/api/achievements/:id', requireUser, async (req, res) => {
    const u = await one('SELECT id, name, role FROM users WHERE id = $1', [int(req.params.id)]);
    if (!u) throw new HttpError(404, 'Pessoa não encontrada.');
    if (u.role !== 'aluno') throw new HttpError(400, 'Só alunos têm conquistas.');
    const stats = await getStats(u.id);
    const unlocked = new Map(
      (await q('SELECT code, unlocked_at FROM user_trophies WHERE user_id = $1', [u.id])).map((r) => [r.code, r.unlocked_at]),
    );
    const trophies = TROPHIES.map((t) => ({
      ...t,
      progress: Math.min(stats[t.stat] || 0, t.target),
      unlocked: unlocked.has(t.code),
      unlocked_at: unlocked.get(t.code) || null,
    }));
    const medals = await q(
      `SELECT m.id, m.type, m.reason, m.created_at, pr.id AS prof_id, pr.name AS prof_name
         FROM medals m LEFT JOIN users pr ON pr.id = m.professor_id
        WHERE m.student_id = $1 ORDER BY m.id DESC`,
      [u.id],
    );
    const counts = {};
    for (const m of medals) counts[m.type] = (counts[m.type] || 0) + 1;
    res.json({
      user: u,
      points: await totalPoints(u.id),
      trophies,
      medalTypes: MEDAL_TYPES.map((m) => ({ ...m, count: counts[m.code] || 0 })),
      medals: medals.map((m) => ({ ...m, medal: MEDAL_BY_CODE[m.type] })),
      pointRules: POINT_RULES,
    });
  });

  app.post('/api/medals', requireRole('professor', 'admin'), async (req, res) => {
    res.json(await giveMedal(req.user, req.body));
  });

  app.delete('/api/medals/:id', requireRole('professor', 'admin'), async (req, res) => {
    await revokeMedal(req.user, int(req.params.id));
    res.json({ ok: true });
  });

  app.get('/api/medals/given', requireRole('professor', 'admin'), async (req, res) => {
    const rows = await q(
      `SELECT m.id, m.type, m.reason, m.created_at, s.id AS student_id, s.name AS student_name,
              s.avatar_id AS student_avatar, c.short AS student_course
         FROM medals m JOIN users s ON s.id = m.student_id LEFT JOIN courses c ON c.id = s.course_id
        WHERE m.professor_id = $1 ORDER BY m.id DESC LIMIT 100`,
      [req.user.id],
    );
    res.json({ medals: rows.map((m) => ({ ...m, medal: MEDAL_BY_CODE[m.type] })) });
  });

  // ---------- Ranking ----------
  app.get('/api/ranking', requireUser, async (req, res) => {
    const courseId = req.query.course ? int(req.query.course) : null;
    const period = req.query.period === 'month' ? 'month' : 'all';
    const rows = await ranking({ courseId, period });
    res.json({ ranking: rows });
  });

  // ---------- Mural de avisos ----------
  app.get('/api/notices', requireUser, async (req, res) => {
    const onlyCourse = req.user.role === 'aluno' ? req.user.course_id : null;
    const rows = await q(
      `SELECT n.id, n.title, n.body, n.pinned, n.created_at, n.course_id, c.short AS course,
              u.id AS author_id, u.name AS author_name, u.role AS author_role, u.avatar_id AS author_avatar,
              u.is_guest AS author_guest
         FROM notices n
         LEFT JOIN users u ON u.id = n.author_id
         LEFT JOIN courses c ON c.id = n.course_id
        WHERE ($1::int IS NULL OR n.course_id IS NULL OR n.course_id = $1)
        ORDER BY n.pinned DESC, n.id DESC LIMIT 100`,
      [onlyCourse],
    );
    res.json({ notices: rows });
  });

  app.post('/api/notices', requireRole('professor', 'admin'), async (req, res) => {
    const title = clean(req.body.title, 120);
    const body = clean(req.body.body, 3000);
    if (!title || !body) throw new HttpError(400, 'Preencha o título e o texto do aviso.');
    const courseId = int(req.body.course_id);
    const pinned = req.user.role === 'admin' && Boolean(req.body.pinned);
    const n = await one(
      'INSERT INTO notices (author_id, title, body, course_id, pinned) VALUES ($1, $2, $3, $4, $5) RETURNING id',
      [req.user.id, title, body, courseId, pinned],
    );
    res.json({ id: n.id });
  });

  app.delete('/api/notices/:id', requireRole('professor', 'admin'), async (req, res) => {
    const n = await one('SELECT author_id FROM notices WHERE id = $1', [int(req.params.id)]);
    if (!n) throw new HttpError(404, 'Aviso não encontrado.');
    if (n.author_id !== req.user.id && req.user.role !== 'admin') throw new HttpError(403, 'Só quem publicou pode apagar.');
    await q('DELETE FROM notices WHERE id = $1', [int(req.params.id)]);
    res.json({ ok: true });
  });

  app.use('/api', () => {
    throw new HttpError(404, 'Rota não encontrada.');
  });

  // ---------- App (arquivos estáticos) ----------
  app.use(express.static(publicDir, {
    setHeaders(res, file) {
      if (/\.(html|js|css|webmanifest)$/.test(file) || file.endsWith('sw.js')) res.set('Cache-Control', 'no-cache');
    },
  }));
  app.use((req, res, next) => {
    if (req.method !== 'GET') return next();
    res.set('Cache-Control', 'no-cache');
    res.sendFile(path.join(publicDir, 'index.html'));
  });

  // ---------- Erros ----------
  // eslint-disable-next-line no-unused-vars
  app.use((err, _req, res, _next) => {
    const status = err.status || err.statusCode || 500;
    if (status >= 500) console.error(err);
    const message = status === 413 && !(err instanceof HttpError)
      ? 'Arquivo grande demais.'
      : (err instanceof HttpError || status < 500 ? err.message : 'Erro interno. Tente de novo.');
    res.status(status).json({ error: message });
  });

  return app;
}

const isMain = process.argv[1] && path.resolve(process.argv[1]) === fileURLToPath(import.meta.url);
if (isMain) {
  const app = await createApp();
  app.listen(config.port, () => {
    console.log(`\n  Maxx rodando em http://localhost:${config.port}`);
    console.log(`  Banco: ${dbKind() === 'postgres' ? 'PostgreSQL (DATABASE_URL)' : 'PGlite local (pasta data/)'}`);
    if (config.bancaEnabled) {
      console.log(`  Link da banca: http://localhost:${config.port}/?banca=${encodeURIComponent(config.bancaCode)}`);
    }
    console.log('');
  });
}

