6	export class HttpError extends Error {
7	  constructor(status, message) {
8	    super(message);
9	    this.status = status;
10	  }
11	}
12	
13	// ---------- Imagens ----------
14	const ALLOWED_MIME = ['image/jpeg', 'image/png', 'image/webp'];
15	const MAX_IMAGE_BYTES = 4 * 1024 * 1024;
16	
17	export async function saveImageFromDataUrl(dataUrl, ownerId) {
18	  const m = /^data:([a-z/+-]+);base64,(.+)$/i.exec(String(dataUrl || ''));
19	  if (!m) throw new HttpError(400, 'Imagem inválida.');
20	  const mime = m[1].toLowerCase();
21	  if (!ALLOWED_MIME.includes(mime)) throw new HttpError(400, 'Formato de imagem não suportado. Use JPG, PNG ou WEBP.');
22	  const buf = Buffer.from(m[2], 'base64');
23	  if (buf.length === 0) throw new HttpError(400, 'Imagem vazia.');
24	  if (buf.length > MAX_IMAGE_BYTES) throw new HttpError(413, 'Imagem muito grande (máx. 4 MB).');
25	  return saveImage(mime, buf, ownerId);
26	}
27	
28	export async function saveImage(mime, buf, ownerId = null) {
29	  const row = await one('INSERT INTO images (mime, data, owner_id) VALUES ($1, $2, $3) RETURNING id', [mime, buf, ownerId]);
30	  return row.id;
31	}
