33	// ---------- Pontos ----------
34	async function addPoints(userId, amount, kind, ref) {
35	  await q('INSERT INTO points (user_id, amount, kind, ref) VALUES ($1, $2, $3, $4)', [userId, amount, kind, ref]);
36	}
37	
38	export async function totalPoints(userId, since = null) {
39	  const r = await one(
40	    'SELECT COALESCE(SUM(amount), 0)::int AS pts FROM points WHERE user_id = $1 AND ($2::timestamptz IS NULL OR created_at >= $2)',
41	    [userId, since],
42	  );
43	  return r.pts;
44	}
45	
46	// ---------- Troféus ----------
47	export async function getStats(userId) {
48	  return one(
49	    `SELECT
50	      (SELECT count(*) FROM posts WHERE user_id = $1 AND kind = 'foto')::int AS posts,
51	      (SELECT count(*) FROM likes l JOIN posts p ON p.id = l.post_id WHERE p.user_id = $1 AND l.user_id <> $1)::int AS "likesReceived",
52	      (SELECT count(*) FROM comments WHERE user_id = $1)::int AS "commentsMade",
53	      (SELECT count(*) FROM likes WHERE user_id = $1)::int AS "likesGiven",
54	      (SELECT count(*) FROM medals WHERE student_id = $1)::int AS medals,
55	      (SELECT count(DISTINCT type) FROM medals WHERE student_id = $1)::int AS "medalTypes",
56	      (SELECT CASE WHEN avatar_id IS NOT NULL AND length(bio) > 0 THEN 1 ELSE 0 END FROM users WHERE id = $1)::int AS profile`,
57	    [userId],
58	  );
59	}
60	
61	// Confere se o aluno desbloqueou algum troféu novo. Devolve a lista dos novos.
62	export async function checkTrophies(userId) {
63	  const user = await one('SELECT role FROM users WHERE id = $1', [userId]);
64	  if (!user || user.role !== 'aluno') return [];
65	  const stats = await getStats(userId);
66	  const have = new Set((await q('SELECT code FROM user_trophies WHERE user_id = $1', [userId])).map((r) => r.code));
67	  const unlocked = [];
68	  for (const t of TROPHIES) {
69	    if (have.has(t.code) || (stats[t.stat] || 0) < t.target) continue;
70	    const ins = await q(
71	      'INSERT INTO user_trophies (user_id, code) VALUES ($1, $2) ON CONFLICT DO NOTHING RETURNING code',
72	      [userId, t.code],
73	    );
74	    if (!ins.length) continue; // outra requisição chegou primeiro
75	    await addPoints(userId, t.points, 'trofeu', `trophy:${t.code}`);
76	    await q("INSERT INTO posts (user_id, kind, ref_code) VALUES ($1, 'trofeu', $2)", [userId, t.code]);
77	    unlocked.push(t);
78	  }
79	  return unlocked;
80	}
81	
82	// ---------- Publicações ----------
83	export async function createPost(user, { image, caption }) {
84	  if (user.role !== 'aluno') throw new HttpError(403, 'Só alunos publicam fotos no feed.');
85	  caption = String(caption || '').trim().slice(0, 1000);
86	  const imageId = await saveImageFromDataUrl(image, user.id);
87	  const post = await one(
88	    "INSERT INTO posts (user_id, kind, image_id, caption) VALUES ($1, 'foto', $2, $3) RETURNING id",
89	    [user.id, imageId, caption],
90	  );
91	  const today = await one(
92	    "SELECT count(*)::int AS n FROM points WHERE user_id = $1 AND kind = 'post' AND created_at >= $2",
93	    [user.id, startOfTodayBR()],
94	  );
95	  const earned = today.n < POINTS.postsPerDay ? POINTS.post : 0;
96	  if (earned) await addPoints(user.id, earned, 'post', `post:${post.id}`);
97	  const trophies = await checkTrophies(user.id);
98	  return { id: post.id, earned, trophies };
99	}
100	
101	export async function deletePost(user, postId) {
102	  const post = await one('SELECT * FROM posts WHERE id = $1', [postId]);
103	  if (!post) throw new HttpError(404, 'Publicação não encontrada.');
104	  if (post.kind !== 'foto') throw new HttpError(400, 'Conquistas não podem ser apagadas por aqui.');
105	  if (post.user_id !== user.id && user.role !== 'admin') throw new HttpError(403, 'Você não pode apagar esta publicação.');
106	  await q("DELETE FROM points WHERE ref = $1 OR ref LIKE $2", [`post:${postId}`, `like:${postId}:%`]);
107	  await q('DELETE FROM posts WHERE id = $1', [postId]);
108	  if (post.image_id) await q('DELETE FROM images WHERE id = $1', [post.image_id]);
109	}
110	
111	export async function toggleLike(user, postId) {
112	  const post = await one('SELECT id, user_id FROM posts WHERE id = $1', [postId]);
113	  if (!post) throw new HttpError(404, 'Publicação não encontrada.');
114	  const removed = await q('DELETE FROM likes WHERE post_id = $1 AND user_id = $2 RETURNING post_id', [postId, user.id]);
115	  let liked;
116	  const ref = `like:${postId}:${user.id}`;
117	  if (removed.length) {
118	    liked = false;
119	    await q('DELETE FROM points WHERE ref = $1', [ref]);
120	  } else {
121	    liked = true;
122	    const ins = await q(
123	      'INSERT INTO likes (post_id, user_id) VALUES ($1, $2) ON CONFLICT DO NOTHING RETURNING post_id',
124	      [postId, user.id],
125	    );
126	    if (ins.length && post.user_id !== user.id) {
127	      const owner = await one('SELECT role FROM users WHERE id = $1', [post.user_id]);
128	      if (owner?.role === 'aluno') await addPoints(post.user_id, POINTS.likeReceived, 'curtida', ref);
129	    }
130	    await checkTrophies(post.user_id);
131	    await checkTrophies(user.id);
132	  }
133	  const c = await one('SELECT count(*)::int AS n FROM likes WHERE post_id = $1', [postId]);
134	  return { liked, likes: c.n };
135	}
136	
137	export async function addComment(user, postId, body) {
138	  body = String(body || '').trim().slice(0, 500);
139	  if (!body) throw new HttpError(400, 'Escreva alguma coisa.');
140	  const post = await one('SELECT id FROM posts WHERE id = $1', [postId]);
141	  if (!post) throw new HttpError(404, 'Publicação não encontrada.');
142	  const c = await one(
143	    'INSERT INTO comments (post_id, user_id, body) VALUES ($1, $2, $3) RETURNING id, created_at',
144	    [postId, user.id, body],
145	  );
146	  await checkTrophies(user.id);
147	  return c;
148	}
149	
150	export async function deleteComment(user, commentId) {
151	  const c = await one(
152	    'SELECT c.*, p.user_id AS post_owner FROM comments c JOIN posts p ON p.id = c.post_id WHERE c.id = $1',
153	    [commentId],
154	  );
155	  if (!c) throw new HttpError(404, 'Comentário não encontrado.');
156	  if (c.user_id !== user.id && c.post_owner !== user.id && user.role !== 'admin') {
157	    throw new HttpError(403, 'Você não pode apagar este comentário.');
158	  }
159	  await q('DELETE FROM comments WHERE id = $1', [commentId]);
160	}
161	
162	// ---------- Medalhas ----------
163	const MEDALS_PER_DAY = 30;
164	
165	export async function giveMedal(prof, { student_id, type, reason }) {
166	  if (prof.role !== 'professor' && prof.role !== 'admin') throw new HttpError(403, 'Só professores dão medalhas.');
167	  const medal = MEDAL_BY_CODE[type];
168	  if (!medal) throw new HttpError(400, 'Tipo de medalha inválido.');
169	  reason = String(reason || '').trim().slice(0, 300);
170	  if (!reason) throw new HttpError(400, 'Conte o motivo da medalha — o aluno vai ver.');
171	  const student = await one('SELECT id, role FROM users WHERE id = $1', [Number(student_id)]);
172	  if (!student || student.role !== 'aluno') throw new HttpError(400, 'Escolha um aluno.');
173	  const today = await one(
174	    'SELECT count(*)::int AS n FROM medals WHERE professor_id = $1 AND created_at >= $2',
175	    [prof.id, startOfTodayBR()],
176	  );
177	  if (today.n >= MEDALS_PER_DAY) throw new HttpError(429, `Limite de ${MEDALS_PER_DAY} medalhas por dia atingido.`);
178	  const row = await one(
179	    'INSERT INTO medals (student_id, professor_id, type, reason) VALUES ($1, $2, $3, $4) RETURNING id',
180	    [student.id, prof.id, type, reason],
181	  );
182	  await addPoints(student.id, medal.points, 'medalha', `medal:${row.id}`);
183	  await q("INSERT INTO posts (user_id, kind, ref_id) VALUES ($1, 'medalha', $2)", [student.id, row.id]);
184	  const trophies = await checkTrophies(student.id);
185	  return { id: row.id, points: medal.points, trophies };
186	}
187	
188	export async function revokeMedal(user, medalId) {
189	  const m = await one('SELECT * FROM medals WHERE id = $1', [medalId]);
190	  if (!m) throw new HttpError(404, 'Medalha não encontrada.');
191	  if (m.professor_id !== user.id && user.role !== 'admin') throw new HttpError(403, 'Só quem deu a medalha pode retirá-la.');
192	  await q('DELETE FROM points WHERE ref = $1', [`medal:${medalId}`]);
193	  const posts = await q("SELECT id FROM posts WHERE kind = 'medalha' AND ref_id = $1", [medalId]);
194	  for (const p of posts) await q('DELETE FROM points WHERE ref LIKE $1', [`like:${p.id}:%`]);
195	  await q("DELETE FROM posts WHERE kind = 'medalha' AND ref_id = $1", [medalId]);
196	  await q('DELETE FROM medals WHERE id = $1', [medalId]);
197	}
198	
199	// ---------- Ranking ----------
200	export async function ranking({ courseId = null, period = 'all' } = {}) {
201	  const since = period === 'month' ? startOfMonthBR() : null;
202	  return q(
203	    `SELECT u.id, u.name, u.avatar_id, u.is_guest, u.course_id, c.short AS course,
204	            COALESCE(SUM(p.amount), 0)::int AS points
205	       FROM users u
206	       LEFT JOIN courses c ON c.id = u.course_id
207	       LEFT JOIN points p ON p.user_id = u.id AND ($1::timestamptz IS NULL OR p.created_at >= $1)
208	      WHERE u.role = 'aluno' AND ($2::int IS NULL OR u.course_id = $2)
209	      GROUP BY u.id, c.short
210	      ORDER BY points DESC, u.name ASC`,
211	    [since, courseId],
212	  );
213	}
214	
215	export async function positions(user) {
216	  if (user.role !== 'aluno') return { general: null, course: null };
217	  const all = await ranking();
218	  const general = all.findIndex((r) => r.id === user.id) + 1 || null;
219	  const sameCourse = all.filter((r) => r.course_id === user.course_id);
220	  const course = sameCourse.findIndex((r) => r.id === user.id) + 1 || null;
221	  return { general, course, totalGeneral: all.length, totalCourse: sameCourse.length };
222	}
223	
224	export { TROPHY_BY_CODE };
