// Camada de banco de dados.
// - Se a variável DATABASE_URL existir (ex.: banco gratuito no Neon), usa PostgreSQL de verdade.
// - Se não existir, usa o PGlite: um PostgreSQL embutido que salva tudo na pasta ./data.
// Os dois falam o mesmo SQL, então o resto do código não precisa saber qual está em uso.
import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const here = path.dirname(fileURLToPath(import.meta.url));
let impl = null;

export async function initDb({ dataDir } = {}) {
  if (impl) return impl;
  const url = process.env.DATABASE_URL;
  if (url) {
    const { default: pg } = await import('pg');
    const local = /localhost|127\.0\.0\.1/.test(url);
    const pool = new pg.Pool({
      connectionString: url,
      ssl: local ? false : { rejectUnauthorized: false },
      max: 5,
    });
    impl = {
      kind: 'postgres',
      query: (sql, params) => pool.query(sql, params),
      exec: (sql) => pool.query(sql),
      close: () => pool.end(),
    };
  } else {
    const { PGlite } = await import('@electric-sql/pglite');
    const dir = dataDir || process.env.DATA_DIR || path.join(here, '..', 'data', 'pglite');
    if (dir !== 'memory') fs.mkdirSync(dir, { recursive: true });
    const db = dir === 'memory' ? await PGlite.create() : await PGlite.create(dir);
    impl = {
      kind: 'pglite',
      query: (sql, params) => db.query(sql, params),
      exec: (sql) => db.exec(sql),
      close: () => db.close(),
    };
  }
  const schema = fs.readFileSync(path.join(here, 'schema.sql'), 'utf8');
  await impl.exec(schema);
  return impl;
}

export async function q(sql, params = []) {
  const res = await impl.query(sql, params);
  return res.rows;
}

export async function one(sql, params = []) {
  const rows = await q(sql, params);
  return rows[0] || null;
}

export async function closeDb() {
  if (impl) {
    await impl.close();
    impl = null;
  }
}

export function dbKind() {
  return impl ? impl.kind : null;
}

