1	// Configurações que podem ser trocadas por variáveis de ambiente (no Render: aba "Environment").
2	const list = (v, def) => (v ?? def).split(',').map((s) => s.trim().toLowerCase()).filter(Boolean);
3	
4	export const config = {
5	  port: Number(process.env.PORT) || 3000,
6	  // Domínios de e-mail aceitos no cadastro. Só quem tem e-mail da UniMax consegue criar conta.
7	  emailDomains: list(process.env.EMAIL_DOMAINS, 'unimax.edu.br,aluno.unimax.edu.br'),
8	  // Código que o professor precisa digitar para se cadastrar como professor.
9	  professorCode: process.env.PROFESSOR_CODE || 'PROFESSOR-UNIMAX',
10	  // Acesso rápido da banca (sem cadastro). BANCA_ENABLED=false desliga.
11	  bancaEnabled: (process.env.BANCA_ENABLED || 'true').toLowerCase() !== 'false',
12	  // Código da banca. Vazio = não pede código.
13	  bancaCode: process.env.BANCA_CODE ?? 'banca2026',
14	  // Senha da conta da secretaria (admin) criada nos dados de exemplo.
15	  adminPassword: process.env.ADMIN_PASSWORD || 'admin-unimax',
16	  // Senha das contas de exemplo (alunos e professores fictícios).
17	  demoPassword: process.env.DEMO_PASSWORD || 'maxx123',
18	  // Cria dados de exemplo quando o banco está vazio.
19	  seedDemo: (process.env.SEED_DEMO || 'true').toLowerCase() !== 'false',
20	};
21	
22	// Brasil não tem horário de verão desde 2019: UTC-3 fixo.
23	const BR_OFFSET_MS = 3 * 60 * 60 * 1000;
24	
25	export function startOfTodayBR() {
26	  const now = new Date(Date.now() - BR_OFFSET_MS);
27	  return new Date(Date.UTC(now.getUTCFullYear(), now.getUTCMonth(), now.getUTCDate()) + BR_OFFSET_MS);
28	}
29	
30	export function startOfMonthBR() {
31	  const now = new Date(Date.now() - BR_OFFSET_MS);
32	  return new Date(Date.UTC(now.getUTCFullYear(), now.getUTCMonth(), 1) + BR_OFFSET_MS);
33	}
