// ---------------------------------------------------------------- layout
function layout({ title = '', back = false, tab = null, right = '' } = {}, html = '<div class="spinner"></div>') {
  const me = state.me;
  const left = back
    ? `<button class="icon-btn" data-back aria-label="Voltar">${I.back}</button>`
    : '<a href="#/" class="logo" aria-label="Maxx — início">Maxx</a>';
  const meBtn = right || (me ? `<a href="#/perfil/${me.id}" aria-label="Meu perfil">${avatar(me.id, me.name, me.avatar_id, 34)}</a>` : '');
  const plus = isAluno()
    ? `<a href="#/novo" class="plus ${tab === 'novo' ? 'active' : ''}" aria-label="Publicar foto"><span class="plus-btn">${I.plus}</span></a>`
    : `<a href="#/medalha" class="plus ${tab === 'novo' ? 'active' : ''}" aria-label="Dar medalha"><span class="plus-btn">${I.medal}</span></a>`;
  const navItem = (key, href, icon, label) => `<a href="${href}" class="${tab === key ? 'active' : ''}">${icon}<span>${label}</span></a>`;
  root.className = 'app';
  root.innerHTML = `
    <header class="topbar">
      <div style="min-width:40px">${left}</div>
      ${title ? `<div class="title">${esc(title)}</div>` : '<div class="grow"></div>'}
      <div style="min-width:40px;display:flex;justify-content:flex-end">${meBtn}</div>
    </header>
    <main class="view" id="view">${html}</main>
    <nav class="bottomnav" aria-label="Menu principal"><div class="inner">
      ${navItem('feed', '#/', I.home, 'Feed')}
      ${navItem('avisos', '#/avisos', I.mural, 'Avisos')}
      ${plus}
      ${navItem('ranking', '#/ranking', I.ranking, 'Ranking')}
      ${navItem('conquistas', '#/conquistas', I.trophy, 'Conquistas')}
    </div></nav>`;
  return $('#view');
}

function bareLayout(html) {
  root.className = 'app no-nav';
  root.innerHTML = `<main class="view">${html}</main>`;
  return $('.view');
}

