async function noticesScreen() {
  const me = state.me;
  const view = layout({ title: 'Mural de avisos', tab: 'avisos' }, `
    ${isStaff() ? `<button class="btn primary block" id="new-notice" style="margin-bottom:12px">📣 Publicar aviso</button>
    <form class="card pad stack" id="nform" hidden style="margin-bottom:14px">
      <label class="field"><span>Título</span><input class="input" name="title" maxlength="120" required></label>
      <label class="field"><span>Aviso</span><textarea class="input" name="body" maxlength="3000" required></textarea></label>
      <label class="field"><span>Para quem?</span><select class="input" name="course_id">${courseOptions(null, { placeholder: 'Todos os cursos' })}</select></label>
      ${me.role === 'admin' ? '<label class="row small"><input type="checkbox" name="pinned" value="1"> Fixar no topo</label>' : ''}
      <div class="row"><button type="button" class="btn outline grow" id="cancel-notice">Cancelar</button><button class="btn primary grow" type="submit">Publicar</button></div>
    </form>` : ''}
    <div id="list"><div class="spinner"></div></div>`);
  const form = $('#nform', view);
  if (form) {
    $('#new-notice', view).addEventListener('click', () => { form.hidden = false; $('#new-notice', view).hidden = true; form.querySelector('input').focus(); });
    $('#cancel-notice', view).addEventListener('click', () => { form.hidden = true; $('#new-notice', view).hidden = false; });
    onSubmit(form, async (d) => {
      await api('/api/notices', { method: 'POST', body: { ...d, pinned: Boolean(d.pinned) } });
      toast('Aviso publicado!');
      noticesScreen();
    });
  }
  try {
    const { notices } = await api('/api/notices');
    const list = $('#list', view);
    list.innerHTML = notices.length ? notices.map((n) => {
      const official = n.author_role === 'admin';
      const canDel = n.author_id === me.id || me.role === 'admin';
      return `<article class="card notice ${n.pinned ? 'pinned' : ''}">
        <div class="row">
          <a href="#/perfil/${n.author_id}">${avatar(n.author_id, n.author_name, n.author_avatar, 36)}</a>
          <div class="grow"><div class="bold small ellipsis">${esc(n.author_name)} ${roleBadge(n.author_role, n.author_guest)}</div>
          <div class="tiny muted">${timeAgo(n.created_at)}</div></div>
          ${canDel ? `<button class="icon-btn" data-del-notice="${n.id}" aria-label="Apagar aviso">${I.trash}</button>` : ''}
        </div>
        <div class="row" style="gap:6px;margin-top:10px;flex-wrap:wrap">
          ${n.pinned ? '<span class="badge admin">📌 Fixado</span>' : ''}
          <span class="badge">${n.course ? esc(n.course) : 'Todos os cursos'}</span>
          ${official ? '<span class="badge prof">Oficial UniMax</span>' : ''}
        </div>
        <h3>${esc(n.title)}</h3><div class="body">${esc(n.body)}</div></article>`;
    }).join('') : '<div class="empty"><div class="big">📭</div>Nenhum aviso por enquanto.</div>';
    list.addEventListener('click', async (e) => {
      const b = e.target.closest('[data-del-notice]');
      if (!b || !confirm('Apagar este aviso?')) return;
      try {
        await api(`/api/notices/${b.dataset.delNotice}`, { method: 'DELETE' });
        b.closest('.notice').remove();
      } catch (err) { toast(err.message); }
    });
  } catch (err) { $('#list', view).innerHTML = `<div class="empty">${esc(err.message)}</div>`; }
}

