664	async function noticesScreen() {
665	  const me = state.me;
666	  const view = layout({ title: 'Mural de avisos', tab: 'avisos' }, `
667	    ${isStaff() ? `<button class="btn primary block" id="new-notice" style="margin-bottom:12px">📣 Publicar aviso</button>
668	    <form class="card pad stack" id="nform" hidden style="margin-bottom:14px">
669	      <label class="field"><span>Título</span><input class="input" name="title" maxlength="120" required></label>
670	      <label class="field"><span>Aviso</span><textarea class="input" name="body" maxlength="3000" required></textarea></label>
671	      <label class="field"><span>Para quem?</span><select class="input" name="course_id">${courseOptions(null, { placeholder: 'Todos os cursos' })}</select></label>
672	      ${me.role === 'admin' ? '<label class="row small"><input type="checkbox" name="pinned" value="1"> Fixar no topo</label>' : ''}
673	      <div class="row"><button type="button" class="btn outline grow" id="cancel-notice">Cancelar</button><button class="btn primary grow" type="submit">Publicar</button></div>
674	    </form>` : ''}
675	    <div id="list"><div class="spinner"></div></div>`);
676	  const form = $('#nform', view);
677	  if (form) {
678	    $('#new-notice', view).addEventListener('click', () => { form.hidden = false; $('#new-notice', view).hidden = true; form.querySelector('input').focus(); });
679	    $('#cancel-notice', view).addEventListener('click', () => { form.hidden = true; $('#new-notice', view).hidden = false; });
680	    onSubmit(form, async (d) => {
681	      await api('/api/notices', { method: 'POST', body: { ...d, pinned: Boolean(d.pinned) } });
682	      toast('Aviso publicado!');
683	      noticesScreen();
684	    });
685	  }
686	  try {
687	    const { notices } = await api('/api/notices');
688	    const list = $('#list', view);
689	    list.innerHTML = notices.length ? notices.map((n) => {
690	      const official = n.author_role === 'admin';
691	      const canDel = n.author_id === me.id || me.role === 'admin';
692	      return `<article class="card notice ${n.pinned ? 'pinned' : ''}">
693	        <div class="row">
694	          <a href="#/perfil/${n.author_id}">${avatar(n.author_id, n.author_name, n.author_avatar, 36)}</a>
695	          <div class="grow"><div class="bold small ellipsis">${esc(n.author_name)} ${roleBadge(n.author_role, n.author_guest)}</div>
696	          <div class="tiny muted">${timeAgo(n.created_at)}</div></div>
697	          ${canDel ? `<button class="icon-btn" data-del-notice="${n.id}" aria-label="Apagar aviso">${I.trash}</button>` : ''}
698	        </div>
699	        <div class="row" style="gap:6px;margin-top:10px;flex-wrap:wrap">
700	          ${n.pinned ? '<span class="badge admin">📌 Fixado</span>' : ''}
701	          <span class="badge">${n.course ? esc(n.course) : 'Todos os cursos'}</span>
702	          ${official ? '<span class="badge prof">Oficial UniMax</span>' : ''}
703	        </div>
704	        <h3>${esc(n.title)}</h3><div class="body">${esc(n.body)}</div></article>`;
705	    }).join('') : '<div class="empty"><div class="big">📭</div>Nenhum aviso por enquanto.</div>';
706	    list.addEventListener('click', async (e) => {
707	      const b = e.target.closest('[data-del-notice]');
708	      if (!b || !confirm('Apagar este aviso?')) return;
709	      try {
710	        await api(`/api/notices/${b.dataset.delNotice}`, { method: 'DELETE' });
711	        b.closest('.notice').remove();
712	      } catch (err) { toast(err.message); }
713	    });
714	  } catch (err) { $('#list', view).innerHTML = `<div class="empty">${esc(err.message)}</div>`; }
715	}
